{
    "$schema": "https://lnav.org/schemas/config-v1.schema.json",
    "apps": {
        "lnav": {
            "api-test": {
                "root": "",
                "description": "Examples of using lnav's external APIs"
            }
        }
    },
    "tuning": {
        "archive-manager": {
            "min-free-space": 33554432,
            "cache-ttl": "2d"
        },
        "piper": {
            "max-size": 10485760,
            "rotations": 4,
            "ttl": "2d"
        },
        "file-vtab": {
            "max-content-size": 33554432
        },
        "logfile": {
            "max-unrecognized-lines": 1000
        },
        "remote": {
            "cache-ttl": "2d",
            "ssh": {
                "command": "ssh",
                "transfer-command": "cat > {0:} && chmod ugo+rx ./{0:}",
                "start-command": "bash -c ./{0:}",
                "flags": "",
                "options": {

                },
                "config": {
                    "BatchMode": "yes",
                    "ConnectTimeout": "10"
                }
            }
        },
        "clipboard": {
            "impls": {
                "MacOS": {
                    "test": "command -v pbcopy",
                    "general": {
                        "write": "pbcopy",
                        "read": "pbpaste -Prefer txt"
                    },
EXIT=0
